import { api } from '@/lib/api'

type StudyRow = {
  id: string
  study_id: string
  name: string
  description?: string
  status?: string
}

async function getAllStudies(): Promise<StudyRow[]> {
  const response = await api.get('/studies')
  return (response.data || []) as StudyRow[]
}

export const studyService = {
  async getStudy(studyId: string, _opts?: any) {
    const studies = await getAllStudies()
    const found =
      studies.find((s) => s.id === studyId) ||
      studies.find((s) => s.study_id === studyId)

    if (!found) {
      return { data: { title: studyId, name: studyId }, study: { title: studyId, name: studyId } }
    }

    // Standalone module expects something like: { data: { title, name } }
    return {
      data: {
        title: found.name,
        name: found.name,
        studyId: found.study_id,
        id: found.id,
      },
      study: {
        title: found.name,
        name: found.name,
      },
    }
  },
}

